-- Generado por scripts/questions-to-sql.mjs. Se puede ejecutar varias veces: no duplica nada.
-- Las preguntas nuevas entran como draft. Las que ya existen se actualizan, y su estado se respeta.

insert into public.questions (id, tech, topic, difficulty, type, correct_index, status, ref_version) values
  ('rt-first-match', 'angular', 'routing', 'medium', 'test', 2, 'draft', 'angular@22'),
  ('rt-redirect-pathmatch', 'angular', 'routing', 'medium', 'test', 0, 'draft', 'angular@22'),
  ('rt-wildcard-last', 'angular', 'routing', 'easy', 'test', 3, 'draft', 'angular@22'),
  ('rt-guard-urltree', 'angular', 'routing', 'medium', 'test', 1, 'draft', 'angular@22'),
  ('rt-guard-false', 'angular', 'routing', 'medium', 'test', 3, 'draft', 'angular@22'),
  ('rt-canmatch-vs-canactivate', 'angular', 'routing', 'hard', 'test', 0, 'draft', 'angular@22'),
  ('rt-lazy-loadcomponent', 'angular', 'routing', 'easy', 'test', 2, 'draft', 'angular@22'),
  ('rt-input-binding', 'angular', 'routing', 'medium', 'test', 1, 'draft', 'angular@22'),
  ('rt-component-reuse', 'angular', 'routing', 'hard', 'test', 3, 'draft', 'angular@22'),
  ('rt-same-url', 'angular', 'routing', 'hard', 'test', 0, 'draft', 'angular@22'),
  ('rt-children-outlet', 'angular', 'routing', 'easy', 'test', 1, 'draft', 'angular@22'),
  ('rt-resolve', 'angular', 'routing', 'medium', 'test', 2, 'draft', 'angular@22'),
  ('rt-routerlink-active', 'angular', 'routing', 'easy', 'test', 3, 'draft', 'angular@22'),
